import * as React from 'react'
import {Suspense} from 'react'
import type {PreloadedQuery} from 'react-relay'

import useDocumentTitle from '../../../../../hooks/useDocumentTitle'
import useUpdateLastPage from '../../../../../hooks/useUpdateLastPage'
import {getAgentPreviewsArg} from '../../../../../rest/agents'
import {getFavoriteAgentPoolsHref} from '../../../../../routes'
import {getAgentPreviewsReady} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import {extractError} from '../../../../../utils/extractError'
import {LAST_AGENTS_PAGE_KEY} from '../../../../../utils/lastPage'
import Loader from '../../../../common/Loader/Loader'
import PageTitle from '../../../../common/PageTitle/PageTitle'
import type {AgentsPagesAgentTypesQuery} from '../../__generated__/AgentsPagesAgentTypesQuery.graphql'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import AgentsToolbar from '../../AgentsOverviewPage/Toolbar/Toolbar'
import AllAgentsTabContainer from '../AllAgentsTab/AllAgentsTab'
import AgentPoolsPlaceholder from '../Placeholder/AgentPoolsPlaceholder'

import AgentPoolsEditFavorite from './EditFavorite/AgentPoolsEditFavorite'

import styles from './FavoriteAgentPools.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

interface Props {
  isEmpty: boolean
  agentTypesQueryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}

function FavoriteAgentPools(props: Props) {
  const {isEmpty, agentTypesQueryRef, dataKey} = props
  const ready = useAppSelector(getAgentPreviewsReady)
  const {agentPreviewsError} = restApi.endpoints.getAllAgentPreviewsNormalized.useQuery(
    getAgentPreviewsArg(),
    {selectFromResult: ({error}) => ({agentPreviewsError: error})},
  )
  const error = extractError(agentPreviewsError)

  useUpdateLastPage(ready, error, LAST_AGENTS_PAGE_KEY, getFavoriteAgentPoolsHref())
  useDocumentTitle('Favorite Agent Pools — TeamCity')

  if (!window.GLOBAL_ERROR_PAGE_DISABLED && error != null) {
    throw error
  }

  return (
    <div className={styles.page}>
      {isEmpty ? (
        <AgentPoolsPlaceholder />
      ) : (
        <>
          <PageTitle>{'Favorite Agent Pools'}</PageTitle>
          <AgentsToolbar>
            <AgentPoolsEditFavorite />
          </AgentsToolbar>
          <div className={styles.content}>
            <Suspense fallback={<Loader />}>
              <AllAgentsTabContainer agentTypesQueryRef={agentTypesQueryRef} dataKey={dataKey} />
            </Suspense>
          </div>
        </>
      )}
    </div>
  )
}

export default React.memo(FavoriteAgentPools)
