import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import classNames from 'classnames'
import {memo} from 'react'
import * as React from 'react'

import AgentAuthDialog from '../../../../common/AgentAuthDialog/AgentAuthDialog'
import {useAuthAgentDialog} from '../../../../common/AgentAuthDialog/AgentAuthDialog.hooks'
import {addAgentHint} from '../../../../packages/Hints/HintItems/Hints.agents'
import {useHint} from '../../../../packages/Hints/Hints.hooks'
import InstallAgentPopup from '../InstallAgentPopup/InstallAgentPopup'

import styles from './InstallAgentDropdown.module.css'

interface AnchorProps {
  active: boolean
}

const PureAnchor = React.memo(function Anchor({active}: AnchorProps) {
  useHint(addAgentHint)
  return (
    <Button dropdown className={styles.anchor} active={active}>
      <span data-hint-container-id={addAgentHint.id}>{'Install agent'}</span>
    </Button>
  )
})

interface Props {
  className?: string
  anchor?: React.ReactNode
}

function InstallAgentDropdown(props: Props) {
  const authDialog = useAuthAgentDialog()

  return (
    <>
      {authDialog.visible && <AgentAuthDialog onClose={authDialog.onClose} />}
      <Dropdown
        className={classNames(styles.dropdown, props.className)}
        anchor={({active}) => (props.anchor ? props.anchor : <PureAnchor active={active} />)}
        data-test="install-agent-button"
      >
        <InstallAgentPopup showAuthAgentDialog={authDialog.show} />
      </Dropdown>
    </>
  )
}

export default memo(InstallAgentDropdown)
