import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import type {PopupMenuAttrs} from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'
import PopupMenu from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'

import {resolveHelpURL} from '../../../../../utils/url'
import HelpLink from '../../../../common/HelpLink/HelpLink'
import {
  dockerAgentImageUrl,
  fullDistributions,
  fullZipFileDistribution,
  isFullDistributions,
  windowsInstallerUrl,
  zipFileDistribution,
} from '../InstallAgent/InstallAgent.consts'

import styles from './InstallAgentPopup.module.css'

type Props = PopupMenuAttrs & {
  showAuthAgentDialog?: () => unknown
}

function InstallAgentPopup({showAuthAgentDialog, ...popupProps}: Props) {
  const data: ListDataItem[] = [
    {
      target: '_blank',
      rel: 'noopener',
      href: windowsInstallerUrl,
      label: 'Windows installer',
      className: styles.link,
      hoverClassName: styles.hoverLink,
    },
    {
      target: '_blank',
      rel: 'noreferrer',
      href: dockerAgentImageUrl,
      label: 'Docker image',
      className: styles.link,
      hoverClassName: styles.hoverLink,
    },
    {
      target: '_blank',
      rel: 'noreferrer',
      href: zipFileDistribution,
      label: 'Minimal ZIP file distribution',
      className: styles.link,
      hoverClassName: styles.hoverLink,
    },
    {
      target: '_blank',
      rel: 'noreferrer',
      href: isFullDistributions ? fullDistributions : fullZipFileDistribution,
      label: isFullDistributions ? 'Full distributions' : 'Full ZIP file distribution',
      className: styles.link,
      hoverClassName: styles.hoverLink,
    },
    {
      rgItemType: PopupMenu.ListProps.Type.CUSTOM,
      className: styles.text,
      disabled: true,
      template: (
        <div>
          {'See our '}
          <HelpLink
            url={resolveHelpURL(
              '?Setting+up+and+Running+Additional+Build+Agents#SettingupandRunningAdditionalBuildAgents-InstallingAdditionalBuildAgents',
            )}
          >
            {'documentation'}
          </HelpLink>
          {' for details.'}
        </div>
      ),
    },
  ]

  if (showAuthAgentDialog != null) {
    data.push(
      {
        rgItemType: PopupMenu.ListProps.Type.SEPARATOR,
      },
      {
        label: 'Use authentication token...',
        onClick: showAuthAgentDialog,
      },
    )
  }

  return (
    <PopupMenu
      className={styles.popup}
      {...popupProps}
      data={data}
      shortcuts
      activateFirstItem
      closeOnSelect
    />
  )
}

export default InstallAgentPopup
