import Button from '@jetbrains/ring-ui-built/components/button/button'
import {memo, useCallback} from 'react'

import {dialog} from '../../../../../../slices'
import {DialogType} from '../../../../../../types'
import {FAVORITE_DIALOG_PAGE_ID} from '../../Dialog/AgentPoolsFavoriteDialog.consts'

import styles from './AgentPoolsEditFavorite.module.css'

import {useAppDispatch} from 'src/hooks/react-redux'

const openEditDialog = () =>
  dialog.actions.open(FAVORITE_DIALOG_PAGE_ID, DialogType.FAVORITE_AGENT_POOLS)

function AgentPoolsEditFavorite() {
  const dispatch = useAppDispatch()
  const openDialog = useCallback(() => dispatch(openEditDialog()), [dispatch])

  return <Button className={styles.button} onClick={openDialog}>{`Configure favorites...`}</Button>
}

export default memo(AgentPoolsEditFavorite)
