import * as React from 'react'
import type {EntryPointProps, PreloadedQuery} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'

import {getAgentsOverviewHref} from '../../../../routes'
import Redirect from '../../../common/Redirect/Redirect'
import type {AgentsPagesAgentTypesQuery} from '../__generated__/AgentsPagesAgentTypesQuery.graphql'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import type {AgentsPagesQueries} from '../AgentsPages.queries'

import type {AgentsPoolsFavoritePageQuery} from './__generated__/AgentsPoolsFavoritePageQuery.graphql'
import {query} from './AgentsPoolsFavoritePage.queries'
import {AgentPoolsFavoriteDialog} from './Dialog/AgentPoolsFavoriteDialog'
import {FAVORITE_DIALOG_PAGE_ID} from './Dialog/AgentPoolsFavoriteDialog.consts'
import FavoriteAgentPools from './FavoriteAgentPools/FavoriteAgentPools'
import {useAgentPoolFavoriteList} from './hooks/useAgentPoolFavorite'
import {useIsAgentPoolFavoriteEnabled} from './hooks/useIsAgentPoolFavoriteEnabled'

type Queries = AgentsPagesQueries & {main: AgentsPoolsFavoritePageQuery}
function AgentsPoolsFavoritePageContainer({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const data = usePreloadedQuery(query, queries.main)
  const isEnabled = useIsAgentPoolFavoriteEnabled()

  if (!isEnabled) {
    return <Redirect to={getAgentsOverviewHref()} replace />
  }

  return <AgentsPoolsFavoritePage agentTypesQueryRef={queries.agentTypes} dataKey={data} />
}

type Props = {
  agentTypesQueryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}
function AgentsPoolsFavoritePage({agentTypesQueryRef, dataKey}: Props) {
  const isEmpty = useAgentPoolFavoriteList().length === 0

  return (
    <>
      <AgentPoolsFavoriteDialog
        id={FAVORITE_DIALOG_PAGE_ID}
        agentTypesQueryRef={agentTypesQueryRef}
      />
      <FavoriteAgentPools
        isEmpty={isEmpty}
        agentTypesQueryRef={agentTypesQueryRef}
        dataKey={dataKey}
      />
    </>
  )
}

export default React.memo(AgentsPoolsFavoritePageContainer)
export type AgentsPoolsFavoritePageContainerComponent = typeof AgentsPoolsFavoritePageContainer
