import classnames from 'classnames'
import type * as React from 'react'

import type {AgentPoolId} from '../../../../../../types'
import {authorizeAgentHint} from '../../../../../packages/Hints/HintItems/Hints.agents'
import {useHint} from '../../../../../packages/Hints/Hints.hooks'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {EXPAND_AGENTS_OVERVIEW_STATE_KEY} from '../../../AgentsPages.effects'
import {useStoredAgentsTreeBranchState} from '../../../AgentsPages.hooks'
import {SORT_ALFABETICALLY, sortSameChildren} from '../../../AgentsPages.utils'
import type {
  AgentSelectionId,
  AgentsTreeAgentNode,
  AgentsTreeAgentTypeNode,
  AgentTreeItemType,
} from '../../../AgentsSidebar/AgentsSidebar.types'
import {UNAUTHORIZED_AGENTS_SELECTION_ID} from '../../../AgentsSidebar/AgentsSidebar.types'
import {isAgentNode, isAgentTypeNode} from '../../../AgentsSidebar/AgentsSidebar.utils'
import AgentsGroup from '../../../components/AgentsGroup/AgentsGroup'
import CloudAgentRow from '../../../components/CloudAgentRow/CloudAgentRow'
import ExpandablePanel from '../../../components/ExpandablePanel/ExpandablePanel'

import ExpandableAgentPoolSubHeading from './SubHeading/ExpandableAgentPoolSubHeading'

import styles from './ExpandableAgentPool.module.css'

type Props = {
  childNodes: ReadonlyArray<AgentsTreeAgentNode | AgentsTreeAgentTypeNode>
  sortingType: string | undefined
  canRemoveAgents?: boolean
  id?: AgentPoolId | AgentSelectionId | string
  type: AgentTreeItemType.POOL | AgentTreeItemType.SELECTION
  title: string | React.ReactNode
  count: number
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}

function ExpandableAgentPool({
  id,
  type,
  title,
  childNodes = [],
  count,
  sortingType = SORT_ALFABETICALLY,
  canRemoveAgents,
  dataKey,
}: Props) {
  const unauthorized = id === UNAUTHORIZED_AGENTS_SELECTION_ID
  useHint(unauthorized && authorizeAgentHint)
  const [open, toggle] = useStoredAgentsTreeBranchState(EXPAND_AGENTS_OVERVIEW_STATE_KEY, type, id)
  const cloudAgentNodes = childNodes.filter(isAgentTypeNode)
  const agentNodes = childNodes.filter(isAgentNode)

  return (
    <ExpandablePanel
      className={styles.expandable}
      headerClassName={styles.header}
      headingClassName={classnames({
        [styles.heading]: unauthorized,
      })}
      subheadingClassName={styles.subheading}
      contentClassName={styles.content}
      heading={title}
      hintId={unauthorized ? authorizeAgentHint.id : null}
      subheading={<ExpandableAgentPoolSubHeading id={id} count={count} />}
      expanded={open}
      content={
        <>
          {cloudAgentNodes.length > 0
            ? sortSameChildren(cloudAgentNodes).map(node => (
                <CloudAgentRow
                  key={node.id}
                  removable={canRemoveAgents}
                  dataKey={dataKey}
                  {...node}
                />
              ))
            : null}
          {agentNodes.length > 0 ? (
            <AgentsGroup
              childNodes={agentNodes}
              sortingType={sortingType}
              canRemoveAgents={canRemoveAgents}
              dataKey={dataKey}
            />
          ) : null}
        </>
      }
      onToggle={toggle}
    />
  )
}

export default ExpandableAgentPool
