import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'
import {memo} from 'react'

import InstallAgentDropdown from '../InstallAgentDropdown/InstallAgentDropdown'

import {fullDistributions, isFullDistributions} from './InstallAgent.consts'

import styles from './InstallAgent.module.css'

interface Props {
  className?: string
  anchor?: React.ReactNode
}

function InstallAgent(props: Props) {
  if (isFullDistributions) {
    return (
      <>
        {props.anchor ? (
          props.anchor
        ) : (
          <Button
            className={classNames(props.className, styles.link)}
            href={fullDistributions}
            target={'_blank'}
            rel="noreferrer"
          >
            {'Install agent'}
          </Button>
        )}
      </>
    )
  } else {
    return <InstallAgentDropdown className={props.className} anchor={props.anchor} />
  }
}

export default memo(InstallAgent)
